index b27476a5311..6fd3c9f9311 100644
--- a/sql/item_subselect.cc
+++ b/sql/item_subselect.cc
@@ -74,6 +74,7 @@
 #include "sql/opt_trace.h"  // OPT_TRACE_TRANSFORM
